package dev.tacticalcombat.client.ui;

import dev.tacticalcombat.uiapi.HudPreferences;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;

/** Local layout editor. Input capture is restricted to this explicitly opened screen. */
public final class HudSettingsScreen extends RpgScreen {
    private HudPreferences draft;
    private HudOptions extra;
    private boolean layout,dirty;
    private String dragging;
    private double offsetX,offsetY;
    private RpgList settings;
    public HudSettingsScreen(Screen parent){super("Customize Cubetable HUD",parent);draft=CubetableHud.preferences();extra=CubetableHud.options();}
    @Override protected void init(){super.init();clearChildren();int x=frame.x()+12,y=frame.y()+36,w=frame.width()-24;button(layout?"Options":"Drag layout","",x,y,110,20,()->{layout=!layout;init();});button("Reset layout","",x+116,y,100,20,()->{draft=CubetableHud.defaults();extra=HudOptions.defaults();dirty=true;init();});if(!layout){settings=addDrawableChild(new RpgList(x,y+26,w,Math.max(38,frame.height()-126),choice->change(choice.id())));rows();}footer();button("Save locally","",frame.x()+frame.width()-112,frame.y()+frame.height()-30,100,20,this::save);message=layout?"Drag a panel; scroll over it to resize. Save persists only local preferences.":"Choose an option to cycle its value. Save changes locally.";}
    private void rows(){var rows=new ArrayList<HubState.Choice>();for(String id:List.of("visible","party","initiative","dice","events","outside","motion","speed","font","logfont","partyfont","dicefont","notifications","sound","duration","bubble","legacy","chat")){String value=switch(id){case "visible"->""+draft.visible();case "party"->""+draft.party().visible();case "initiative"->""+draft.initiative().visible();case "dice"->""+draft.dice().visible();case "events"->""+draft.events().visible();case "outside"->""+extra.outsideCombat();case "motion"->""+draft.reducedMotion();case "speed"->""+draft.animationSpeed();case "font"->""+draft.fontSize();case "logfont"->""+extra.logFont();case "partyfont"->""+extra.partyFont();case "dicefont"->""+extra.diceFont();case "notifications"->""+extra.notificationsVisible();case "sound"->""+extra.sound();case "duration"->extra.notificationTicks()/20.0+" s";case "bubble"->extra.bubbleTicks()/20.0+" s";case "legacy"->""+extra.legacyDice();default->""+extra.diceChat();};rows.add(new HubState.Choice(id,label(id),value,true,"Click to cycle",0));}settings.rows(rows);}
    private static String label(String id){return switch(id){case "outside"->"Party outside combat";case "motion"->"Reduced motion";case "speed"->"Dice animation speed";case "font"->"General HUD font";case "logfont"->"Event log font";case "partyfont"->"Party font";case "dicefont"->"Dice font";case "duration"->"Notification duration";case "bubble"->"Recent roll duration";case "legacy"->"Legacy packet dice mode";case "chat"->"Legacy dice chat echo";default->Character.toUpperCase(id.charAt(0))+id.substring(1)+" visibility";};}
    private void change(String id){var p=draft;HudPreferences.Panel party=p.party(),initiative=p.initiative(),dice=p.dice(),events=p.events();if(id.equals("party"))party=toggle(party);if(id.equals("initiative"))initiative=toggle(initiative);if(id.equals("dice"))dice=toggle(dice);if(id.equals("events"))events=toggle(events);draft=new HudPreferences(1,party,initiative,dice,events,id.equals("font")?(p.fontSize()>=16?8:p.fontSize()+1):p.fontSize(),id.equals("speed")?(p.animationSpeed()>=4?.25:p.animationSpeed()*2):p.animationSpeed(),id.equals("motion")?!p.reducedMotion():p.reducedMotion(),id.equals("visible")?!p.visible():p.visible());var o=extra;extra=new HudOptions(1,o.notifications(),id.equals("logfont")?cycleFont(o.logFont()):o.logFont(),id.equals("partyfont")?cycleFont(o.partyFont()):o.partyFont(),id.equals("dicefont")?cycleFont(o.diceFont()):o.diceFont(),id.equals("outside")?!o.outsideCombat():o.outsideCombat(),id.equals("notifications")?!o.notificationsVisible():o.notificationsVisible(),id.equals("sound")?!o.sound():o.sound(),id.equals("legacy")?!o.legacyDice():o.legacyDice(),id.equals("chat")?!o.diceChat():o.diceChat(),id.equals("duration")?cycleDuration(o.notificationTicks()):o.notificationTicks(),id.equals("bubble")?cycleDuration(o.bubbleTicks()):o.bubbleTicks());dirty=true;rows();}
    private static int cycleFont(int n){return n>=16?8:n+1;}
    private static int cycleDuration(int n){return n>=200?20:n+20;}
    private static HudPreferences.Panel toggle(HudPreferences.Panel p){return new HudPreferences.Panel(p.x(),p.y(),p.scale(),!p.visible());}
    private Map<String,UiLayout.Rect> rectangles(){var result=new LinkedHashMap<String,UiLayout.Rect>();result.put("party",HudSession.bounds(draft.party(),width,height,174,105));result.put("initiative",HudSession.bounds(draft.initiative(),width,height,280,36));result.put("dice",HudSession.bounds(draft.dice(),width,height,222,94));result.put("events",HudSession.bounds(draft.events(),width,height,270,76));result.put("notifications",HudSession.bounds(extra.notifications(),width,height,210,36));return result;}
    private HudPreferences.Panel panel(String id){return switch(id){case "party"->draft.party();case "initiative"->draft.initiative();case "dice"->draft.dice();case "events"->draft.events();default->extra.notifications();};}
    private void update(String id,HudPreferences.Panel next){var p=draft;if(id.equals("notifications")){var o=extra;extra=new HudOptions(1,next,o.logFont(),o.partyFont(),o.diceFont(),o.outsideCombat(),o.notificationsVisible(),o.sound(),o.legacyDice(),o.diceChat(),o.notificationTicks(),o.bubbleTicks());}else draft=new HudPreferences(1,id.equals("party")?next:p.party(),id.equals("initiative")?next:p.initiative(),id.equals("dice")?next:p.dice(),id.equals("events")?next:p.events(),p.fontSize(),p.animationSpeed(),p.reducedMotion(),p.visible());dirty=true;}
    @Override public boolean mouseClicked(double x,double y,int button){if(super.mouseClicked(x,y,button))return true;if(layout&&button==0){var entries=new ArrayList<>(rectangles().entrySet());Collections.reverse(entries);for(var e:entries)if(e.getValue().contains(x,y)){dragging=e.getKey();offsetX=x-e.getValue().x();offsetY=y-e.getValue().y();return true;}}return false;}
    @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(dragging!=null){var r=rectangles().get(dragging);var p=panel(dragging);update(dragging,new HudPreferences.Panel(Math.clamp((x-offsetX-4)/Math.max(1,width-r.width()-8),0,1),Math.clamp((y-offsetY-4)/Math.max(1,height-r.height()-8),0,1),p.scale(),p.visible()));return true;}return super.mouseDragged(x,y,button,dx,dy);}
    @Override public boolean mouseReleased(double x,double y,int button){dragging=null;return super.mouseReleased(x,y,button);}
    @Override public boolean mouseScrolled(double x,double y,double horizontal,double vertical){if(layout){for(var e:rectangles().entrySet())if(e.getValue().contains(x,y)){var p=panel(e.getKey());update(e.getKey(),new HudPreferences.Panel(p.x(),p.y(),Math.clamp(p.scale()+(vertical>0?.1:-.1),.5,2),p.visible()));return true;}}return super.mouseScrolled(x,y,horizontal,vertical);}
    @Override protected void content(DrawContext g,int mx,int my,float delta){if(layout){for(var e:rectangles().entrySet()){var r=e.getValue();RpgTheme.panel(g,r.x(),r.y(),r.width(),r.height(),0xAD191D23,true);RpgTheme.text(g,textRenderer,e.getKey()+" · drag / scroll scale",r.x()+5,r.y()+5,r.width()-10,RpgTheme.GOLD);}}}
    private void save(){try{CubetableHud.save(draft,extra);dirty=false;message="HUD settings saved locally.";messageColor=RpgTheme.SUCCESS;}catch(Exception e){message="Save failed; staged settings retained. "+e.getMessage();messageColor=RpgTheme.ERROR;}}
    @Override public void close(){if(dirty)client.setScreen(new RpgConfirmationScreen(this,"Discard HUD changes?","Unsaved visual settings will be discarded.",()->client.setScreen(parent)));else super.close();}
}
